#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Ticket 59's closing run on the tty: M4's exit from ticket 17, M4's three
# Outputs checklist items (docs/testing/checklist.md), and ticket 60's checks on
# the two monitors, on the installed camino-git. Run it as caminotest, from a
# second login while bare camino runs on a spare tty. ssh from another machine is
# best, since the monitors stay on Camino; from another tty, switch back to
# Camino's (Ctrl+Alt+F<n>) to look. The results are appended to the ticket's
# notes when this copy can write them, and to a file to copy from otherwise.
# They're saved as they're given, so a stopped run resumes where it left off.
#
# The nested M1 to M4 items aren't here. Ticket 43's and 54's wizards walk
# through them on the host desktop, and the last stage says how to run them.

TOTAL_STAGES=12

HERE="$(dirname "$(realpath "$0")")"
TICKET="${TICKET:-$HERE/59-packaging-and-closing-m4.md}"
RESULTS=()   # "short name|pass, FAIL or n/a|note"
FAILED=()
STATE="${XDG_STATE_HOME:-$HOME/.local/state}/camino"
PROGRESS="$STATE/59-closing-checks.progress"
LAYOUT="$STATE/59-layout"
LOG="${CAMINO_LOG:-$HOME/camino.log}"
DEBUG_CALL=(busctl --user call org.mate.Camino.Debug /org/mate/Camino/Debug org.mate.Camino.Debug)
MOUSE=org.mate.peripherals-mouse
TOUCHPAD=org.mate.peripherals-touchpad
KBD=org.mate.peripherals-keyboard-xkb.kbd
CAMINO_PID=
TTY_WL=
TTY_X=

# Every login of caminotest shares one runtime directory and session bus (14), so
# Camino's are this login's. sudo and su don't set them.
export XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
export DBUS_SESSION_BUS_ADDRESS="${DBUS_SESSION_BUS_ADDRESS:-unix:path=$XDG_RUNTIME_DIR/bus}"

# log_value TEXT prints what follows TEXT in the log's last line that has it.
log_value() {
  sed 's/\x1b\[[0-9;]*m//g' "$LOG" | grep -o "$1[^ ]*" | tail -n1 | cut -d= -f2 || true
}
# on_tty CMD... runs a command with Camino's socket and DISPLAY.
on_tty() {
  [[ -n $TTY_X ]] || TTY_X=$(log_value 'Xwayland is ready on DISPLAY=')
  env WAYLAND_DISPLAY="$TTY_WL" ${TTY_X:+DISPLAY="$TTY_X"} "$@"
}
# native CMD... starts a Wayland client on the tty's Camino, detached.
native() { on_tty env -u DISPLAY GDK_BACKEND=wayland setsid "$@" >/dev/null 2>&1 & }
# x11 CMD... starts an X11 client on Camino's Xwayland, detached.
x11() { on_tty env -u WAYLAND_DISPLAY GDK_BACKEND=x11 setsid "$@" >/dev/null 2>&1 & }
# show CMD... runs a command and shows it with its output, indented.
show() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@" 2>&1 | sed 's/^/    /' || true; }
# randr ARGS... runs wlr-randr on the tty's Camino and shows its output.
randr() { show on_tty wlr-randr "$@"; }
# ok "..." prints a check that passed.
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# outputs prints one line per output of DumpState: name, x,y, logical size, scale.
outputs() {
  local reply
  reply=$(on_tty "${DEBUG_CALL[@]}" --json=short DumpState) || return 1
  python3 -c '
import json, sys
for o in json.loads(json.loads(sys.argv[1])["data"][0])["outputs"]:
    g = o["geometry"]
    print(o["name"], "%d,%d" % (g["x"], g["y"]), "%dx%d" % (g["width"], g["height"]), o["scale"])' "$reply"
}
# show_outputs shows what wlr-randr and DumpState say of the outputs.
show_outputs() {
  randr
  say "DumpState's outputs (name, place, logical size, scale):"
  outputs 2>&1 | sed 's/^/    /' || warn "DumpState didn't answer"
}
# restore_layout puts every output back in its preferred mode, at the place and
# scale saved in stage 2. wlr-randr marks what it sends as set, so the outputs
# don't go back to their defaults by themselves (58).
restore_layout() {
  local name place _ scale
  [[ -s $LAYOUT ]] || { warn "no saved layout; restart camino to get the defaults back"; return 0; }
  while read -r name place _ scale; do
    randr --output "$name" --on --preferred --pos "$place" --scale "$scale"
  done < "$LAYOUT"
}

# find_camino finds the Camino on the tty, its socket and its DISPLAY.
find_camino() {
  local exe _
  while true; do
    CAMINO_PID=$(pgrep -n -x -u "$(id -u)" camino || true)
    if [[ -n $CAMINO_PID && -r $LOG ]]; then
      TTY_WL=$(log_value 'listening on WAYLAND_DISPLAY=')
      # Xwayland is ready a moment after the socket.
      for _ in 1 2 3 4 5; do
        TTY_X=$(log_value 'Xwayland is ready on DISPLAY=')
        [[ -n $TTY_X ]] && break
        sleep 1
      done
      [[ -n $TTY_WL ]] && break
    fi
    warn "no running camino of $(id -un) with its socket in $LOG"
    step "Log in as caminotest on a spare tty, and run:  camino 2>~/camino.log"
    pause "Press Enter once it runs"
  done
  ok "camino is pid $CAMINO_PID, on WAYLAND_DISPLAY=$TTY_WL DISPLAY=${TTY_X:-(none yet)}"
  # The link can't be read when Camino was started by another process's login.
  exe=$(readlink /proc/"$CAMINO_PID"/exe 2>/dev/null || true)
  [[ -z $exe || $exe == /usr/bin/camino ]] || warn "it's $exe, not the installed /usr/bin/camino"
}

# result "Short name" records whether the check passed, with an optional note.
result() {
  local name="$1" verdict note=""
  if confirm "Did all of it work? ($name)"; then verdict=pass; else verdict=FAIL; FAILED+=("$name"); fi
  printf '  %sNote (what you saw; Enter for none):%s ' "$BOLD" "$RESET"
  read -r note || true
  RESULTS+=("$name|$verdict|$note")
  printf '%s|%s|%s\n' "$name" "$verdict" "$note" >> "$PROGRESS"
}

# load_progress offers to resume from the results a stopped run saved.
load_progress() {
  local r name verdict note
  mkdir -p "$STATE"
  [[ -s $PROGRESS ]] || return 0
  say "A stopped run saved these results:"
  while IFS= read -r r; do
    IFS='|' read -r name verdict note <<< "$r"
    say "  $verdict  $name${note:+ ($note)}"
  done < "$PROGRESS"
  if confirm "Resume, skipping the stages they cover? (No starts over)"; then
    mapfile -t RESULTS < "$PROGRESS"
    for r in "${RESULTS[@]}"; do
      IFS='|' read -r name verdict _ <<< "$r"
      if [[ $verdict == FAIL ]]; then FAILED+=("$name"); fi
    done
  else
    : > "$PROGRESS"
    rm -f "$LAYOUT"
    # What wlr-randr set stays set (58), so the defaults need a new Camino.
    warn "restart camino before a run that starts over, so its outputs are at their defaults"
  fi
}

# done_already NAME succeeds, and says so, when NAME's result is recorded.
done_already() {
  recorded "$1" || return 1
  say "Already recorded; skipping."
  sleep 1
}
# recorded NAME succeeds when NAME's result is recorded.
recorded() {
  local r
  for r in ${RESULTS[@]+"${RESULTS[@]}"}; do [[ $r == "$1|"* ]] && return 0; done
  return 1
}

# write_results appends the results to the ticket's notes. caminotest can't write
# the developer's checkout, so from there they go to a file to copy from.
write_results() {
  local r name verdict note line target="$TICKET"
  [[ -w $target ]] || target="$STATE/59-closing-results.md"
  if [[ $target == "$TICKET" ]]; then
    grep -q '^## Notes' "$target" || printf '\n## Notes\n' >> "$target"
  fi
  printf '\n- **Closing run on the tty (%s), on %s:**\n' "$(date +%F)" "$(pacman -Q camino-git)" >> "$target"
  for r in "${RESULTS[@]}"; do
    IFS='|' read -r name verdict note <<< "$r"
    line=$(printf '  - %s: %s.%s' "$name" "$verdict" "${note:+ $note}")
    # A resumed run's earlier results may be there already.
    grep -qxF -- "$line" "$target" || printf '%s\n' "$line" >> "$target"
  done
  printf '  %s✓ wrote%s %s results to %s\n' "$GREEN" "$RESET" "${#RESULTS[@]}" "$target"
  [[ $target == "$TICKET" ]] ||
    SKIPPED+=("copying $target into ticket 59's notes")
}

banner "Ticket 59: closing M4 on the tty"
load_progress

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before the checks"
[[ $(id -un) == caminotest ]] || warn "this is $(id -un), not caminotest, the second user (14)"
show pacman -Q camino-git
for tool in wlr-randr busctl gsettings python3 foot pluma xterm wayland-info edid-decode; do
  command -v "$tool" >/dev/null || warn "$tool is missing"
done
say "Both monitors are connected. Camino runs as caminotest on a spare tty:"
step "camino 2>~/camino.log"
note "RUST_LOG=debug camino 2>~/camino.log  also logs the VT switches, for stage 9."
# A resumed run that already quit Camino has only its results left to record.
recorded "Quitting gives the VT back in text mode" || find_camino

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "M4's exit: both monitors at their default scales"
if ! done_already "Bare camino drives both monitors at their default scales"; then
show_outputs
outputs > "$LAYOUT" 2>/dev/null || warn "couldn't save the outputs' layout from DumpState"
say "Opening foot on $TTY_WL."
native foot
step "Both monitors show Camino's picture, each in its preferred mode."
step "The pointer crosses between them where they touch, left to right."
step "Type in foot, and drag it by its titlebar to the other monitor and back."
note "Expected (50): the AOC (DP-1, 1920×1080) at 1.0 and the LG (HDMI-A-1, 3840×2160)"
note "at 1.7, left to right in the order found, the second one's x the first one's"
note "logical width. foot's text is the same physical size, and sharp, on both."
show sh -c 'for e in /sys/class/drm/card*-*/edid; do [ -s "$e" ] && { echo "$e"; edid-decode "$e" 2>/dev/null | grep -E "Display Product Name|Maximum image size|DTD 1"; }; done'
result "Bare camino drives both monitors at their default scales"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Checklist: the scale picked for each monitor"
if ! done_already "The scale picked for each of the developer's monitors"; then
say "Forcing an integer scale with window-scaling-factor."
show on_tty gsettings set org.mate.interface window-scaling-factor 2
sleep 1
show_outputs
step "Both monitors are at 2, and the second one sits at the first one's new right edge."
pause "Press Enter to set it back to 0"
show on_tty gsettings set org.mate.interface window-scaling-factor 0
sleep 1
show_outputs
step "The default scales and places of stage 2 are back."
on_tty gsettings reset org.mate.interface window-scaling-factor || true
result "The scale picked for each of the developer's monitors"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "M4's exit: wlr-randr changes modes, scales and positions"
if ! done_already "wlr-randr changes modes, scales and positions"; then
randr
ask OUT "The output to change (a name from the list, e.g. HDMI-A-1):"
ask MODE "One of its modes that isn't the current one (e.g. 1920x1080):"
randr --output "$OUT" --mode "$MODE"
step "$OUT switches to $MODE, and frames keep coming: move the pointer and a window on it."
pause
randr --output "$OUT" --scale 1.5
step "$OUT is at scale 1.5: windows on it are redrawn at their new size."
pause
note "The other output stays where it is, so pick a place that touches it. Below it is"
note "its x, then its y plus its logical height, from DumpState's list in stage 2."
ask POS "A new place for $OUT, as x,y:"
randr --output "$OUT" --pos "$POS"
step "$OUT is now at $POS, and the pointer crosses between the monitors where they touch."
show_outputs
note "Expected: wlr-randr lists both monitors with all their modes, and the picture,"
note "wlr-randr's list and DumpState follow each change."
result "wlr-randr changes modes, scales and positions"
say "Putting the saved layout back."
restore_layout
pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Ticket 60: a monitor turned off and on"
if ! done_already "wlr-randr turns a monitor off and on"; then
randr
ask OUT "The output to turn off (a name from the list):"
step "First, put foot on $OUT."
pause "Press Enter once foot is on $OUT"
randr --output "$OUT" --off
step "$OUT goes dark, and foot is on the other monitor, which never went black."
show_outputs
pause "Press Enter to turn it on again"
randr --output "$OUT" --on
step "$OUT is lit again, and the pointer and windows can go to it."
show_outputs
result "wlr-randr turns a monitor off and on"
restore_layout
pause
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Checklist: a GTK3 window dragged across a 1.0 and a 2.0 output"
if ! done_already "A GTK3 window dragged across a 1.0 and a 2.0 output"; then
randr
ask HIDPI "The output to set to 2.0, the other one staying at 1.0 (e.g. HDMI-A-1):"
# The places are set too, left to right at the new scales: the saved layout's places
# are set ones (58), and would leave a gap or an overlap beside a rescaled output.
while read -r name x scale; do
  randr --output "$name" --pos "$x,0" --scale "$scale"
done < <(outputs | sort -t' ' -k2 -n | awk -v hidpi="$HIDPI" '{
  split($3, size, "x"); scale = ($1 == hidpi) ? 2 : 1
  print $1, x + 0, scale; x += int(size[1] * $4 / scale + 0.5) }')
say "Opening pluma on $TTY_WL and xterm on ${TTY_X:-Xwayland}."
native pluma
x11 xterm
pause "Press Enter once both have mapped, with pluma on the 1.0 output and a line typed in it"
show on_tty "${DEBUG_CALL[@]}" ToggleFrameDebug
step "Drag pluma slowly by its titlebar onto $HIDPI, stop while it spans both, go on"
step "until it's wholly on $HIDPI, then drag it back the same way."
step "Its content and frame stay the same logical size: it never jumps, doubles or halves."
step "While it spans both, the frame is ×2 and sharp on both. pluma's content goes to"
step "scale 2 as soon as it enters $HIDPI, and back to 1 only once it has wholly left (52)."
step "Wholly on either output, the label is that output's scale, and all is sharp."
step "Then the same with xterm: drawn at the X11 scale, 2, on both (41), its frame as pluma's."
result "A GTK3 window dragged across a 1.0 and a 2.0 output"
show on_tty "${DEBUG_CALL[@]}" ToggleFrameDebug
restore_layout
say "Keep pluma and xterm for the next stage."
pause
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Checklist: hot-plugging a monitor"
if ! done_already "Hot-plugging a monitor"; then
pgrep -u "$(id -u)" -x pluma >/dev/null || native pluma
pgrep -u "$(id -u)" -x xterm >/dev/null || x11 xterm
step "Put pluma and xterm on the right-hand monitor, and maximise one of them."
step "Then unplug the right-hand monitor's cable."
pause "Press Enter once it's unplugged"
show_outputs
step "One output is left, at 0,0. Both windows are on it, the maximised one filling it."
step "They're moved, not resized: one larger than the output hangs over its edge."
step "The monitor that stayed never went black or froze."
step "Plug the cable back in."
pause "Press Enter once it's plugged in"
show_outputs
step "It's lit in its preferred mode at its default scale, to the right of the other."
step "The pointer and the windows can go to it again."
step "Now the same with the left-hand monitor: unplug it."
pause "Press Enter once it's unplugged"
show_outputs
step "Plug it back in."
pause "Press Enter once it's plugged in"
show_outputs
note "A re-plugged monitor comes back to the right of the other, whichever side it was on."
if grep -q "can't light" "$LOG"; then
  warn "the log has can't-light lines:"; grep "can't light" "$LOG" | sed 's/^/    /'
else
  ok "the log has no can't-light line"
fi
result "Hot-plugging a monitor"
say "Close pluma and xterm."
pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "M4's exit: input settings changed with gsettings apply live"
if ! done_already "Mouse settings apply live"; then
show on_tty gsettings set "$MOUSE" left-handed true
step "The mouse's right button now clicks and drags, and its left opens menus."
pause
on_tty gsettings reset "$MOUSE" left-handed || true
show on_tty gsettings set "$MOUSE" motion-acceleration 10
step "The mouse pointer is clearly faster."
pause
on_tty gsettings reset "$MOUSE" motion-acceleration || true
result "Mouse settings apply live"
fi
if ! done_already "Touchpad settings apply live"; then
if confirm "Does this machine have a touchpad?"; then
  show on_tty gsettings set "$TOUCHPAD" tap-to-click false
  step "A tap doesn't click."
  pause
  show on_tty gsettings set "$TOUCHPAD" tap-to-click true
  step "A tap clicks again."
  show on_tty gsettings set "$TOUCHPAD" natural-scroll true
  step "A two-finger scroll in foot (run  seq 200 | less ) goes the other way."
  pause
  on_tty gsettings reset "$TOUCHPAD" tap-to-click || true
  on_tty gsettings reset "$TOUCHPAD" natural-scroll || true
  result "Touchpad settings apply live"
else
  RESULTS+=("Touchpad settings apply live|n/a|The machine has no touchpad.")
  printf '%s\n' "${RESULTS[-1]}" >> "$PROGRESS"
fi
fi
if ! done_already "Keyboard-layout settings apply live"; then
show on_tty gsettings set "$KBD" layouts "['us', 'es']"
show on_tty gsettings set "$KBD" options "['grp\tgrp:alt_shift_toggle']"
step "In foot, type  ;  It types ; with the US layout."
step "Press Alt+Shift, then type ; again: it types ñ. Alt+Shift again goes back."
pause
on_tty gsettings reset "$KBD" layouts || true
on_tty gsettings reset "$KBD" options || true
result "Keyboard-layout settings apply live"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "M4's exit: switching VT away and back"
if ! done_already "Switching VT away and back works"; then
step "On Camino's tty, press Ctrl+Alt+F<n> for another tty: its text console shows."
step "Switch back: both monitors redraw, and the pointer, the keyboard and foot work."
pause "Press Enter once you're back on Camino's tty"
show sh -c "sed 's/\x1b\[[0-9;]*m//g' '$LOG' | grep -E 'the VT was switched|WARN|ERROR' | tail -n 12"
note "With RUST_LOG=debug, the log has  the VT was switched away  and  back."
result "Switching VT away and back works"
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Ticket 60: explicit sync"
if ! done_already "Explicit sync"; then
show on_tty sh -c 'wayland-info | grep wp_linux_drm_syncobj_manager_v1'
if command -v vkcube >/dev/null; then
  say "Running vkcube for 10 seconds, and counting its acquire points."
  show on_tty sh -c 'WAYLAND_DEBUG=1 timeout 10 vkcube --wsi wayland 2>&1 | grep -c set_acquire_point'
elif command -v gtk4-demo >/dev/null; then
  say "Running gtk4-demo for 10 seconds, and counting its acquire points."
  show on_tty sh -c 'WAYLAND_DEBUG=1 GDK_BACKEND=wayland timeout 10 gtk4-demo 2>&1 | grep -c set_acquire_point'
else
  warn "neither vkcube (vulkan-tools) nor gtk4-demo (gtk4-demos) is installed"
fi
note "Expected: the global is listed, the count isn't 0, and the client's picture"
note "moved without stalls or tearing."
result "Explicit sync"
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Quitting gives the tty back"
if ! done_already "Quitting gives the VT back in text mode"; then
if confirm "Stop camino (SIGTERM to pid $CAMINO_PID)?"; then
  kill -TERM "$CAMINO_PID" || warn "camino (pid $CAMINO_PID) wasn't running any more"
  step "Camino's tty is back in text mode, at caminotest's shell prompt."
  result "Quitting gives the VT back in text mode"
else
  SKIPPED+=("the quit check")
fi
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Record the results"
for r in "${RESULTS[@]}"; do
  IFS='|' read -r name verdict note <<< "$r"
  say "$verdict  $name${note:+ ($note)}"
done
if confirm "Write these down?"; then
  write_results
  rm -f "$PROGRESS" "$LAYOUT"
  (( ${#FAILED[@]} )) && SKIPPED+=("a new ticket for each failure: ${FAILED[*]}")
else
  SKIPPED+=("recording the results in ticket 59 (they stay in $PROGRESS)")
fi
SKIPPED+=("the nested M1 to M3 items, as the developer on the host desktop, from the checkout's issues directory, with tools/dev-nested (no --bin):  TICKET=\$PWD/59-packaging-and-closing-m4.md ./43-closing-checks.sh")
SKIPPED+=("the nested M4 layout item, the same way, also without the --bin its wizard names:  TICKET=\$PWD/59-packaging-and-closing-m4.md ./54-hand-checks.sh")
SKIPPED+=("a line in ticket 60's notes that points to these results, for its criteria")
SKIPPED+=("a push, with CI and the Packaging job green, before the Close M4 On the metal commit")
pause

finish
